{"cmd": "cat > internal/store/store.go <<'EOF'
// Package store owns the SQLite file and every write the service performs.
package store

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"net/url"
	"sort"
	"strings"

	_ "modernc.org/sqlite"
)

// Sentinel errors let the API layer map storage failures to published error codes.
var (
	ErrInvalidAsset = errors.New("invalid asset")
	ErrLineageCycle = errors.New("lineage cycle")
	ErrAssetNotFound = errors.New("asset not found")
)

// Asset is the catalog record returned by every successful registration or listing.
type Asset struct {
	ID         string   `json:"id"`
	Type       string   `json:"type"`
	Owner      string   `json:"owner"`
	Upstream   []string `json:"upstream"`
	Downstream []string `json:"downstream"`
}

// UpstreamAsset is an Asset annotated with its shortest distance from the query target.
type UpstreamAsset struct {
	ID         string   `json:"id"`
	Type       string   `json:"type"`
	Owner      string   `json:"owner"`
	Upstream   []string `json:"upstream"`
	Downstream []string `json:"downstream"`
	Distance   int      `json:"distance"`
}

// Store wraps the SQLite handle so callers never touch database/sql directly.
type Store struct {
	db *sql.DB
}

// Open prepares the database file and the schema this service needs.
func Open(path string) (*Store, error) {
	query := url.Values{}
	query.Add("_pragma", "busy_timeout(5000)")
	query.Add("_pragma", "foreign_keys(on)")
	dsn := (&url.URL{Scheme: "file", Path: path, RawQuery: query.Encode()}).String()

	db, err := sql.Open("sqlite", dsn)
	if err != nil {
		return nil, fmt.Errorf("open sqlite: %w", err)
	}
	if _, err := db.Exec("PRAGMA journal_mode=WAL"); err != nil {
		db.Close()
		return nil, fmt.Errorf("enable wal: %w", err)
	}
	if _, err := db.Exec(schema); err != nil {
		db.Close()
		return nil, fmt.Errorf("apply schema: %w", err)
	}
	return &Store{db: db}, nil
}

// Ping reports whether the storage layer is usable.
func (s *Store) Ping() error { return s.db.Ping() }

// Close releases the database handle.
func (s *Store) Close() error { return s.db.Close() }

// PutAsset registers a new asset or fully replaces the fields and both dependency
// lists of an existing one. The upsert, the edge replacement and the cycle check
// run in a single transaction: callers either see the complete new state or none
// of it. The returned Asset carries the deduplicated dependency lists.
func (s *Store) PutAsset(in *Asset) (bool, *Asset, error) {
	upstream := dedup(in.Upstream)
	downstream := dedup(in.Downstream)

	ctx := context.Background()
	conn, err := s.db.Conn(ctx)
	if err != nil {
		return false, nil, err
	}
	defer conn.Close()
	// IMMEDIATE takes the writer lock up front so concurrent registrations serialize
	// instead of deadlocking while upgrading deferred transactions.
	if _, err := conn.ExecContext(ctx, "BEGIN IMMEDIATE"); err != nil {
		return false, nil, err
	}
	committed := false
	defer func() {
		if !committed {
			_, _ = conn.ExecContext(ctx, "ROLLBACK")
		}
	}()

	var created bool
	if err := conn.QueryRowContext(ctx,
		`SELECT EXISTS(SELECT 1 FROM assets WHERE id = ?)`, in.ID).Scan(&created); err != nil {
		return false, nil, err
	}

	refs := make([]string, 0, len(upstream)+len(downstream))
	refs = append(refs, upstream...)
	refs = append(refs, downstream...)
	if len(refs) > 0 {
		placeholders := strings.Repeat("?,", len(refs))
		placeholders = placeholders[:len(placeholders)-1]
		rows, err := conn.QueryContext(ctx,
			`SELECT id FROM assets WHERE id IN (`+placeholders+`)`, stringsToAny(refs)...)
		if err != nil {
			return false, nil, err
		}
		registered := map[string]struct{}{}
		for rows.Next() {
			var id string
			if err := rows.Scan(&id); err != nil {
				rows.Close()
				return false, nil, err
			}
			registered[id] = struct{}{}
		}
		if err := rows.Close(); err != nil {
			return false, nil, err
		}
		for _, ref := range refs {
			if _, ok := registered[ref]; !ok {
				return false, nil, ErrInvalidAsset
			}
		}
	}

	// Rebuild the union graph from every other asset's declarations plus the
	// candidate declarations, so edges independently declared by neighbours are
	// kept even when this asset drops its own declaration.
	edges := map[[2]string]struct{}{}
	rows, err := conn.QueryContext(ctx,
		`SELECT asset_id, direction, ref_id FROM asset_refs WHERE asset_id <> ?`, in.ID)
	if err != nil {
		return false, nil, err
	}
	for rows.Next() {
		var assetID, direction, refID string
		if err := rows.Scan(&assetID, &direction, &refID); err != nil {
			rows.Close()
			return false, nil, err
		}
		addEdge(edges, assetID, direction, refID)
	}
	if err := rows.Close(); err != nil {
		return false, nil, err
	}
	for _, ref := range upstream {
		edges[[2]string{ref, in.ID}] = struct{}{}
	}
	for _, ref := range downstream {
		edges[[2]string{in.ID, ref}] = struct{}{}
	}
	if createsCycle(edges, in.ID) {
		return false, nil, ErrLineageCycle
	}

	if _, err := conn.ExecContext(ctx, `
		INSERT INTO assets (id, type, owner) VALUES (?, ?, ?)
		ON CONFLICT(id) DO UPDATE SET type = excluded.type, owner = excluded.owner`,
		in.ID, in.Type, in.Owner); err != nil {
		return false, nil, err
	}
	if _, err := conn.ExecContext(ctx, `DELETE FROM asset_refs WHERE asset_id = ?`, in.ID); err != nil {
		return false, nil, err
	}
	for position, ref := range upstream {
		if err := insertRef(ctx, conn, in.ID, "upstream", ref, position); err != nil {
			return false, nil, err
		}
	}
	for position, ref := range downstream {
		if err := insertRef(ctx, conn, in.ID, "downstream", ref, position); err != nil {
			return false, nil, err
		}
	}

	if _, err := conn.ExecContext(ctx, "COMMIT"); err != nil {
		return false, nil, err
	}
	committed = true

	return created, &Asset{
		ID:         in.ID,
		Type:       in.Type,
		Owner:      in.Owner,
		Upstream:   upstream,
		Downstream: downstream,
	}, nil
}

// ListAssets returns assets ordered by id. When typeFilter is empty every asset
// is returned; otherwise only assets whose type matches exactly are returned.
func (s *Store) ListAssets(typeFilter string) ([]Asset, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return nil, err
	}
	defer tx.Rollback()

	query := `SELECT id, type, owner FROM assets`
	args := []any{}
	if typeFilter != "" {
		query += ` WHERE type = ?`
		args = append(args, typeFilter)
	}
	query += ` ORDER BY id ASC`

	rows, err := tx.Query(query, args...)
	if err != nil {
		return nil, err
	}
	assets := []Asset{}
	for rows.Next() {
		var asset Asset
		if err := rows.Scan(&asset.ID, &asset.Type, &asset.Owner); err != nil {
			rows.Close()
			return nil, err
		}
		assets = append(assets, asset)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}

	groups, err := loadRefGroups(tx)
	if err != nil {
		return nil, err
	}
	for i := range assets {
		assets[i].Upstream = groups[assets[i].ID].upstream
		assets[i].Downstream = groups[assets[i].ID].downstream
	}
	return assets, tx.Commit()
}

// Upstream returns every asset reachable by following upstream edges from id,
// each annotated with its shortest reachability distance. depth <= 0 means no
// limit; otherwise ancestors farther than depth are excluded. Results are sorted
// by distance ascending and then by id ascending; each ancestor appears once.
func (s *Store) Upstream(id string, depth int) (string, []UpstreamAsset, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return "", nil, err
	}
	defer tx.Rollback()

	var exists string
	if err := tx.QueryRow(`SELECT id FROM assets WHERE id = ?`, id).Scan(&exists); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return "", nil, ErrAssetNotFound
		}
		return "", nil, err
	}

	rows, err := tx.Query(`SELECT id, type, owner FROM assets`)
	if err != nil {
		return "", nil, err
	}
	type assetRow struct {
		typ, owner string
	}
	records := map[string]assetRow{}
	for rows.Next() {
		var assetID, typ, owner string
		if err := rows.Scan(&assetID, &typ, &owner); err != nil {
			rows.Close()
			return "", nil, err
		}
		records[assetID] = assetRow{typ: typ, owner: owner}
	}
	if err := rows.Close(); err != nil {
		return "", nil, err
	}

	groups, err := loadRefGroups(tx)
	if err != nil {
		return "", nil, err
	}

	// Reverse adjacency: edge (from -> to) means "to" depends on "from", so the
	// upstreams of "to" are the keys reachable by following edges backwards.
	reverse := map[string]map[string]struct{}{}
	for groupID, group := range groups {
		for _, up := range group.upstream {
			if reverse[groupID] == nil {
				reverse[groupID] = map[string]struct{}{}
			}
			reverse[groupID][up] = struct{}{}
		}
		for _, down := range group.downstream {
			if reverse[down] == nil {
				reverse[down] = map[string]struct{}{}
			}
			reverse[down][groupID] = struct{}{}
		}
	}

	distances := map[string]int{id: 0}
	queue := []string{id}
	for len(queue) > 0 {
		current := queue[0]
		queue = queue[1:]
		if depth > 0 && distances[current] >= depth {
			continue
		}
		for next := range reverse[current] {
			if _, seen := distances[next]; !seen {
				distances[next] = distances[current] + 1
				queue = append(queue, next)
			}
		}
	}
	delete(distances, id)

	ids := make([]string, 0, len(distances))
	for ancestor := range distances {
		ids = append(ids, ancestor)
	}
	sort.Slice(ids, func(i, j int) bool {
		if distances[ids[i]] != distances[ids[j]] {
			return distances[ids[i]] < distances[ids[j]]
		}
		return ids[i] < ids[j]
	})

	upstreams := make([]UpstreamAsset, 0, len(ids))
	for _, ancestor := range ids {
		record := records[ancestor]
		upstreams = append(upstreams, UpstreamAsset{
			ID:         ancestor,
			Type:       record.typ,
			Owner:      record.owner,
			Upstream:   groups[ancestor].upstream,
			Downstream: groups[ancestor].downstream,
			Distance:   distances[ancestor],
		})
	}
	return id, upstreams, tx.Commit()
}

