func (s *Store) beginImmediate() (*sql.Tx, *sql.Conn, error) {
	conn, err := s.db.Conn(nil)
	if err != nil {
		return nil, nil, err
	}
	if _, err := conn.ExecContext(nil, "BEGIN IMMEDIATE"); err != nil {
		conn.Close()
		return nil, nil, err
	}
	tx, err := conn.BeginTx(nil, &sql.TxOptions{})
	if err != nil {
		conn.ExecContext(nil, "ROLLBACK")
		conn.Close()
		return nil, nil, err
	}
	return tx, conn, nil
}

// reaches reports whether a walk from start reaches target using the given adjacency map.
func reaches(adjacency map[string]map[string]bool, start, target string) bool {
	visited := map[string]bool{start: true}
	frontier := []string{start}
	for len(frontier) > 0 {
		node := frontier[0]
		frontier = frontier[1:]
		for next := range adjacency[node] {
			if next == target {
				return true
			}
			if !visited[next] {
				visited[next] = true
				frontier = append(frontier, next)
			}
		}
	}
	return false
}

func dedupeNonEmpty(values []string) []string {
	seen := map[string]bool{}
	result := []string{}
	for _, value := range values {
		if value == "" || seen[value] {
			continue
		}
		seen[value] = true
		result = append(result, value)
	}
	return result
}

