	fmt.Printf("inUse after Exec: %+v\n", db.Stats())

	fmt.Println("begin")
	tx, err := db.BeginTx(nil, nil)
	if err != nil { panic(err) }
	tx.Rollback()
	fmt.Println("OK")
}
EOF
